package com.creatorhub.dao;
import com.creatorhub.model.*; import com.creatorhub.util.DBConnection; import java.sql.*; import java.util.*;
public class CreatorDAO {
 public Student login(String email,String hash)throws SQLException{String q="SELECT s.*,p.role_title,p.about_me,p.skills,p.work_text FROM students s LEFT JOIN profiles p ON s.student_id=p.student_id WHERE s.email=? AND s.password_hash=?"; try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement(q)){p.setString(1,email);p.setString(2,hash);try(ResultSet r=p.executeQuery()){return r.next()?student(r):null;}}}
 public Student student(int id)throws SQLException{String q="SELECT s.*,p.role_title,p.about_me,p.skills,p.work_text FROM students s LEFT JOIN profiles p ON s.student_id=p.student_id WHERE s.student_id=?";try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement(q)){p.setInt(1,id);try(ResultSet r=p.executeQuery()){return r.next()?student(r):null;}}}
 private Student student(ResultSet r)throws SQLException{Student s=new Student();s.setStudentId(r.getInt("student_id"));s.setName(r.getString("name"));s.setEmail(r.getString("email"));s.setPasswordHash(r.getString("password_hash"));s.setRoleTitle(r.getString("role_title"));s.setAboutMe(r.getString("about_me"));s.setSkills(r.getString("skills"));s.setWorkText(r.getString("work_text"));return s;}
 public void updateProfile(Student s)throws SQLException{String q="UPDATE profiles SET role_title=?,about_me=?,skills=?,work_text=? WHERE student_id=?";try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement(q)){p.setString(1,s.getRoleTitle());p.setString(2,s.getAboutMe());p.setString(3,s.getSkills());p.setString(4,s.getWorkText());p.setInt(5,s.getStudentId());p.executeUpdate();}}
 private String base(){return "SELECT c.*,s.name creator_name,(SELECT COUNT(*) FROM votes v WHERE v.collab_id=c.collab_id) vote_count,(SELECT COUNT(*) FROM applications a WHERE a.collab_id=c.collab_id) application_count FROM collaborations c JOIN students s ON c.creator_id=s.student_id ";}
 public List<Collaboration> collaborations(String cat,int uid)throws SQLException{String q=base()+"WHERE c.status='Open' "+((cat!=null&&!cat.isEmpty())?"AND c.category=? ":"")+"ORDER BY c.created_at DESC";List<Collaboration> out=new ArrayList<>();try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement(q)){if(cat!=null&&!cat.isEmpty())p.setString(1,cat);try(ResultSet r=p.executeQuery()){while(r.next())out.add(collab(r,c,uid));}}return out;}
 public List<Collaboration> trending(int uid)throws SQLException{String q=base()+"WHERE c.status='Open' ORDER BY vote_count DESC,c.created_at DESC LIMIT 3";List<Collaboration> out=new ArrayList<>();try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement(q);ResultSet r=p.executeQuery()){while(r.next())out.add(collab(r,c,uid));}return out;}
 private Collaboration collab(ResultSet r,Connection c,int uid)throws SQLException{Collaboration x=new Collaboration();x.setCollabId(r.getInt("collab_id"));x.setCreatorId(r.getInt("creator_id"));x.setCreatorName(r.getString("creator_name"));x.setTitle(r.getString("title"));x.setCategory(r.getString("category"));x.setDescription(r.getString("description"));x.setRequiredRole(r.getString("required_role"));x.setStatus(r.getString("status"));x.setVoteCount(r.getInt("vote_count"));x.setApplicationCount(r.getInt("application_count"));if(uid>0){try(PreparedStatement p=c.prepareStatement("SELECT 1 FROM votes WHERE collab_id=? AND voter_id=?")){p.setInt(1,x.getCollabId());p.setInt(2,uid);try(ResultSet a=p.executeQuery()){x.setVoted(a.next());}}}return x;}
 public void create(Collaboration x)throws SQLException{String q="INSERT INTO collaborations(creator_id,title,category,description,required_role) VALUES(?,?,?,?,?)";try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement(q)){p.setInt(1,x.getCreatorId());p.setString(2,x.getTitle());p.setString(3,x.getCategory());p.setString(4,x.getDescription());p.setString(5,x.getRequiredRole());p.executeUpdate();}}
 public boolean vote(int cid,int uid)throws SQLException{if(hasVote(cid,uid))return false;try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement("INSERT INTO votes(collab_id,voter_id) VALUES(?,?)")){p.setInt(1,cid);p.setInt(2,uid);p.executeUpdate();return true;}catch(SQLIntegrityConstraintViolationException e){return false;}}
 private boolean hasVote(int cid,int uid)throws SQLException{try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement("SELECT 1 FROM votes WHERE collab_id=? AND voter_id=?")){p.setInt(1,cid);p.setInt(2,uid);try(ResultSet r=p.executeQuery()){return r.next();}}}
 public boolean apply(Application a)throws SQLException{try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement("INSERT INTO applications(collab_id,applicant_id,pitch_text) VALUES(?,?,?)")){p.setInt(1,a.getCollabId());p.setInt(2,a.getApplicantId());p.setString(3,a.getPitchText());p.executeUpdate();return true;}catch(SQLIntegrityConstraintViolationException e){return false;}}
 public List<Collaboration> myCollaborations(int uid)throws SQLException{String q=base()+"WHERE c.creator_id=? ORDER BY c.created_at DESC";List<Collaboration> out=new ArrayList<>();try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement(q)){p.setInt(1,uid);try(ResultSet r=p.executeQuery()){while(r.next())out.add(collab(r,c,uid));}}return out;}
 public List<Application> applications(int uid)throws SQLException{String q="SELECT a.*,s.name applicant_name,s.email applicant_email FROM applications a JOIN students s ON a.applicant_id=s.student_id JOIN collaborations c ON a.collab_id=c.collab_id WHERE c.creator_id=? ORDER BY a.applied_at DESC";List<Application> out=new ArrayList<>();try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement(q)){p.setInt(1,uid);try(ResultSet r=p.executeQuery()){while(r.next()){Application a=new Application();a.setApplicationId(r.getInt("application_id"));a.setCollabId(r.getInt("collab_id"));a.setApplicantId(r.getInt("applicant_id"));a.setApplicantName(r.getString("applicant_name"));a.setApplicantEmail(r.getString("applicant_email"));a.setPitchText(r.getString("pitch_text"));out.add(a);}}}return out;}
 public List<Challenge> challenges(int uid)throws SQLException{String q="SELECT c.*,(SELECT COUNT(*) FROM challenge_participants p WHERE p.challenge_id=c.challenge_id) participant_count,EXISTS(SELECT 1 FROM challenge_participants p2 WHERE p2.challenge_id=c.challenge_id AND p2.student_id=?) joined FROM challenges c ORDER BY c.deadline";List<Challenge> out=new ArrayList<>();try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement(q)){p.setInt(1,uid);try(ResultSet r=p.executeQuery()){while(r.next()){Challenge x=new Challenge();x.setChallengeId(r.getInt("challenge_id"));x.setTitle(r.getString("title"));x.setCategory(r.getString("category"));x.setDescription(r.getString("description"));x.setDeadline(r.getString("deadline"));x.setTeamSize(r.getString("team_size"));x.setPrize(r.getString("prize"));x.setParticipantCount(r.getInt("participant_count"));x.setJoined(r.getBoolean("joined"));out.add(x);}}}return out;}
 public boolean join(int cid,int uid)throws SQLException{try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement("INSERT INTO challenge_participants(challenge_id,student_id) VALUES(?,?)")){p.setInt(1,cid);p.setInt(2,uid);p.executeUpdate();return true;}catch(SQLIntegrityConstraintViolationException e){return false;}}
}
